/**
 * Colors that do not map onto the standard role pairs: the outgoing bubble is
 * a filled accent in light mode and a muted container in dark mode, and the
 * composer/send action reuses that same pairing.
 *
 * These are derived from the active scheme rather than pinned, so a
 * wallpaper-derived palette (or the system contrast level) flows through to
 * the bubbles, and every bubble keeps its matching `on` color for contrast.
 */
@Immutable
data class MessageBubbleColors(
    val outgoing: Color,
    val onOutgoing: Color,
    val incoming: Color,
    val onIncoming: Color,
    /** Quote block inside a bubble, and its primary text color. */
    val outgoingQuote: Color,
    val onOutgoingQuote: Color,
    val incomingQuote: Color,
    val onIncomingQuote: Color,
    val accent: Color,
    val composerAccent: Color,
    val onComposerAccent: Color,
)

fun messageBubbleColors(scheme: ColorScheme, darkTheme: Boolean): MessageBubbleColors =
    if (darkTheme) {
        MessageBubbleColors(
            outgoing = scheme.primaryContainer,
            onOutgoing = scheme.onPrimaryContainer,
            incoming = scheme.surfaceContainerHigh,
            onIncoming = scheme.onSurface,
            outgoingQuote = scheme.surfaceContainerLowest,
            onOutgoingQuote = scheme.onSurface,
            incomingQuote = scheme.surfaceContainerLowest,
            onIncomingQuote = scheme.onSurface,
            accent = scheme.primary,
            composerAccent = scheme.primaryContainer,
            onComposerAccent = scheme.onPrimaryContainer,
        )
    } else {
        MessageBubbleColors(
            outgoing = scheme.primary,
            onOutgoing = scheme.onPrimary,
            incoming = scheme.surfaceContainerHigh,
            onIncoming = scheme.onSurface,
            outgoingQuote = scheme.primaryContainer,
            onOutgoingQuote = scheme.onPrimaryContainer,
            incomingQuote = scheme.surfaceContainerLow,
            onIncomingQuote = scheme.onSurface,
            accent = scheme.primary,
            composerAccent = scheme.primary,
            onComposerAccent = scheme.onPrimary,
        )
    }

val LocalMessageBubbleColors = staticCompositionLocalOf {
    messageBubbleColors(LightColorScheme, darkTheme = false)
}
